import { useState } from 'react';
import { Tabs, Tab, Tag } from '@gener8v/ui';

const SECTIONS = ['Overview', 'Invoices', 'Contacts', 'Activity'] as const;
type Section = (typeof SECTIONS)[number];

const invoices = [
  { id: 'INV-1042', issued: '2026-10-01', amount: '12,400.00', status: 'Paid' },
  { id: 'INV-1057', issued: '2026-10-15', amount: '8,250.00', status: 'Overdue' },
  { id: 'INV-1063', issued: '2026-11-01', amount: '9,900.00', status: 'Open' },
];
const variant = { Paid: 'success', Overdue: 'danger', Open: 'neutral' } as const;

const contacts = [
  { name: 'Maya Okafor', role: 'Finance lead', email: 'maya@northwind.example' },
  { name: 'Jon Reyes', role: 'Procurement', email: 'jon@northwind.example' },
];

const activity = [
  { time: '2026-11-03', title: 'Invoice INV-1063 sent', body: 'Delivered to Maya Okafor.' },
  { time: '2026-10-22', title: 'Reminder sent', body: 'INV-1057 payment reminder.' },
  { time: '2026-10-01', title: 'Invoice INV-1042 paid', body: 'Received in full.' },
];

const id = (s: Section, part: 'tab' | 'panel') => `customer-${part}-${s.toLowerCase()}`;

export function App() {
  const [section, setSection] = useState<Section>('Overview');

  return (
    <main className="container section stack">
      <header className="stack">
        <h1>Northwind Traders</h1>
        <p className="lede muted">Customer since March 2022 · Account owner Priya Shah</p>
      </header>

      <Tabs aria-label="Customer sections" onSelectIndex={(i) => setSection(SECTIONS[i]!)}>
        {SECTIONS.map((s) => (
          <Tab key={s} id={id(s, 'tab')} controls={id(s, 'panel')} selected={s === section}
            onClick={() => setSection(s)}>
            {s}
          </Tab>
        ))}
      </Tabs>

      {SECTIONS.map((s) => (
        <section key={s} id={id(s, 'panel')} role="tabpanel" aria-labelledby={id(s, 'tab')}
          hidden={s !== section} tabIndex={0} className="stack">
          {s === 'Overview' && (
            <div className="row">
              <div className="stat">
                <span className="stat-label">Outstanding</span>
                <span className="stat-value num">18,150.00</span>
              </div>
              <div className="stat">
                <span className="stat-label">Paid this year</span>
                <span className="stat-value num">12,400.00</span>
              </div>
              <div className="stat">
                <span className="stat-label">Open invoices</span>
                <span className="stat-value num">2</span>
              </div>
            </div>
          )}
          {s === 'Invoices' && (
            <div className="table-wrap">
              <table className="table">
                <thead>
                  <tr><th>Invoice</th><th>Issued</th><th>Amount</th><th>Status</th></tr>
                </thead>
                <tbody>
                  {invoices.map((i) => (
                    <tr key={i.id}>
                      <td className="mono">{i.id}</td>
                      <td className="num">{i.issued}</td>
                      <td className="num">{i.amount}</td>
                      <td><Tag variant={variant[i.status as keyof typeof variant]}>{i.status}</Tag></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
          {s === 'Contacts' && (
            <div className="table-wrap">
              <table className="table">
                <thead><tr><th>Name</th><th>Role</th><th>Email</th></tr></thead>
                <tbody>
                  {contacts.map((c) => (
                    <tr key={c.email}><td>{c.name}</td><td>{c.role}</td><td className="mono">{c.email}</td></tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
          {s === 'Activity' && (
            <ol className="timeline">
              {activity.map((a) => (
                <li key={a.title} className="timeline-item">
                  <span className="timeline-marker" aria-hidden="true" />
                  <time className="timeline-time">{a.time}</time>
                  <div className="timeline-title">{a.title}</div>
                  <div className="timeline-body">{a.body}</div>
                </li>
              ))}
            </ol>
          )}
        </section>
      ))}
    </main>
  );
}
